{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.uc_final_item_master AS WITH inventory_data AS ( SELECT \"Item SkuCode\" AS sku, sum(COALESCE(NULLIF(TRIM(inventory), \'\')::INTEGER, 0)) as sellable_uc, sum(COALESCE(NULLIF(TRIM(\"Bad Inventory\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(inventory), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Inventory Blocked\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Inventory Not Synced\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Not Found\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Putaway Pending\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Putback Pending\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Stock In Transfer\"), \'\')::INTEGER, 0)) as total_uc FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND facility IN (\'SAPL_EMIZA\', \'SAPL-WH2\', \'SAPL-WH1\') group by 1 ), am as ( select distinct sku_group as keyuniq, sku_class,sales_last_15_days, sales_last_30_days, sales_last_7_days, natural_ros, CASE WHEN POSITION(\'-\' IN \"SKU_GROUP\") > 0 AND LEFT(\"SKU_GROUP\", 2) = \'SH\' THEN UPPER(SPLIT_PART(\"SKU_GROUP\", \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(SKU_GROUP, \'-\', 2)) WHEN POSITION(\'-\' IN \"SKU_GROUP\") > 0 THEN UPPER(SPLIT_PART(\"SKU_GROUP\", \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(SKU_GROUP, \'-\', 2)) ELSE UPPER(\"SKU_GROUP\") END AS sku_group1 from snitch_db.maplemonk.availability_master_v2 ), shopify_data as ( SELECT * FROM ( SELECT MIN(publishedat::DATE) AS live_date, LEFT(VARIANT.value:sku::STRING, LENGTH(VARIANT.value:sku::STRING) - CHARINDEX(\'-\', REVERSE(VARIANT.value:sku::STRING))) AS sku_group, VARIANT.value:sku::STRING AS sku, VARIANT.value:price::NUMBER AS price, VARIANT.value:compareAtPrice::NUMBER AS compare_at_price, CASE WHEN compare_at_price >= price THEN compare_at_price ELSE price END AS SF_MRP, status, ROW_NUMBER() OVER (PARTITION BY VARIANT.value:sku::STRING ORDER BY MAX(ifnull(publishedat::DATE,\'2021-01-01\')) DESC) AS rn FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql , TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT GROUP BY 2, 3, 4, 5, 6, 7 ) t QUALIFY rn = 1 ), logic_inventory AS ( select logicusercode as sku, sum(stock_qty) as logic_total from snitch_db.maplemonk.LOgicerp23_24_get_stock_in_hand where date = current_date group by 1 ), fk_mrp_data as ( select distinct sku, mrp as mp_mrp from snitch_db.maplemonk.S3_MARKETPLACE_MRP where channel = \'FLIPKART\' ), my_mrp_data as ( SELECT DISTINCT SKU, UPPER(REGEXP_SUBSTR(SKU, \'^[^-]+-[^-]+\')) AS SKU_G, MRP AS MP_MRP FROM snitch_db.maplemonk.S3_MARKETPLACE_MRP WHERE channel = \'MYNTRA\' ), aj_mrp_data as ( select distinct sku, mrp as mp_mrp from snitch_db.maplemonk.S3_MARKETPLACE_MRP where channel = \'AJIO\' ), am_mrp_data as ( select distinct sku, mrp as mp_mrp from snitch_db.maplemonk.S3_MARKETPLACE_MRP where channel = \'AMAZON\' ) , nykaa_mrp_data as ( select distinct sku, mrp as mp_mrp from snitch_db.maplemonk.S3_MARKETPLACE_MRP where channel = \'NYKAA\' ) , logic_item_master AS ( SELECT sku AS logic_sku, cost_price::integer as logic_cp, base_price::integer as logic_bp, mrp::integer as logic_mrp FROM SNITCH_DB.MAPLEMONK.LOGIC_FINAL_ITEM_MASTER ), final as ( SELECT UPPER(\"Category Code\") AS category_code, UPPER(\"Product Code\") AS sku, UPPER(name) AS name, UPPER(description) AS style, \"Scan Identifier\", UPPER(\"Requires Customization\") AS requires_customization, \"Length (mm)\", \"Width (mm)\", \"Height (mm)\", \"Weight (gms)\", ean, upc, isbn, color AS uc_color, size, brand, \"Item Detail Fields\", tags, \"Image Url\", \"Product Page Url\", \"Tax Type Code\", \"GST Tax Type Code\", coalesce(nullif(trim(\"Base Price\"),\'\'),0)::integer AS base_price, coalesce(nullif(trim(\"Cost Price\"),\'\'),0)::integer AS cost_price, tat, coalesce(nullif(trim(mrp),\'\'),0)::integer AS MRP, updated, \"Category Name\", enabled, type, \"Component Product Code\", \"Component Quantity\", \"Component Price\", \"HSN CODE\", \"Tax Calculation Type\", \"Batch Group\", \"GRN expiry tolerance (in days)\", \"Dispatch expiry tolerance (in days)\", \"Return expiry tolerance (in days)\", expirable, \"Determine Expiry From\", \"Shelf Life\", \"Expiry Date\", \"Sku Type\", fragile, \"Dangerous Good\", CASE WHEN POSITION(\'-\' IN \"Product Code\") > 0 AND LEFT(\"Product Code\", 2) = \'SH\' AND LENGTH(\"Product Code\") <10 THEN UPPER(SPLIT_PART(\"Product Code\", \'-\', 1)) WHEN POSITION(\'-\' IN \"Product Code\") > 0 THEN UPPER(SPLIT_PART(\"Product Code\", \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(\"Product Code\", \'-\', 2)) ELSE UPPER(\"Product Code\") END AS sku_group, COALESCE(inv.sellable_uc, 0) AS sellable_uc, COALESCE(inv.total_uc, 0) AS total_uc, COALESCE(sim.logic_total,0) as total_logic, coalesce(total_uc+total_logic,0) as total_universe, logic_mrp, logic_cp, logic_bp, sf_mrp, CASE WHEN sf_mrp is null then \'MISSING ON SHOPIFY\' WHEN sf_mrp = mrp THEN \'CORRECT\' ELSE \'INCORRECT\' END as SFxUC_MRP_MATCH, CASE WHEN logic_cp is null THEN \'MISSING ON LOGIC\' WHEN ifnull(logic_cp,0) = ifnull(cost_price,0) THEN \'CORRECT\' ELSE \'INCORRECT\' END AS CP_MATCH, CASE WHEN logic_bp is null THEN \'MISSING ON LOGIC\' WHEN ifnull(logic_bp,0) = ifnull(base_price,0) THEN \'CORRECT\' ELSE \'INCORRECT\' END AS BP_MATCH, CASE WHEN logic_mrp is null THEN \'MISSING ON LOGIC\' WHEN ifnull(nullif(trim(logic_mrp),\'\'),0) = ifnull(nullif(trim(MRP),\'\'),0) THEN \'CORRECT\' ELSE \'INCORRECT\' END AS MRP_MATCH, CASE WHEN mrp_match like \'%MISS%\' THEN \'MISSING\' WHEN cp_match like \'%MISS%\' THEN \'MISSING\' WHEN bp_match like \'%MISS%\' THEN \'MISSING\' WHEN mrp_match = \'INCORRECT\' THEN \'INCORRECT\' WHEN cp_match = \'INCORRECT\' THEN \'INCORRECT\' WHEN bp_match = \'INCORRECT\' THEN \'INCORRECT\' ELSE \'CORRECT\' END AS FINAL_CHECK_STATUS, fk.mp_mrp as FK_MRP, az.mp_mrp as AMAZON_MRP, aj.mp_mrp as AJIO_MRP, my.mp_mrp as MYNTRA_MRP, ny.mp_mrp as NYKAA_MRP, CASE WHEN TRY_CAST(fk_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(fk_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(fk_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS FK_MRP_STATUS, CASE WHEN TRY_CAST(amazon_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(amazon_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(amazon_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS AMAZON_MRP_STATUS, CASE WHEN TRY_CAST(ajio_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(ajio_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(ajio_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS AJIO_MRP_STATUS, CASE WHEN TRY_CAST(nykaa_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(nykaa_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(nykaa_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS NYKAA_MRP_STATUS, CASE WHEN TRY_CAST(myntra_mrp AS NUMBER) IS NULL THEN \'UNLISTED\' WHEN ROUND(MRP, 2) = ROUND(TRY_CAST(myntra_mrp AS NUMBER), 2) THEN \'CORRECT\' WHEN ABS(ROUND(MRP, 2) - ROUND(TRY_CAST(myntra_mrp AS NUMBER), 2)) / ROUND(MRP, 2) > 0.2 THEN \'JACKED\' ELSE \'INCORRECT\' END AS MYNTRA_MRP_STATUS, sd.status as shopify_status, sku_class, sales_last_15_days, sales_last_30_days, sales_last_7_days, natural_ros FROM snitch_db.maplemonk.get_item_master im LEFT JOIN inventory_data inv ON UPPER(im.\"Product Code\") = UPPER(inv.sku) LEFT JOIN logic_item_master lim ON UPPER(im.\"Product Code\") = UPPER(logic_sku) LEFT JOIN logic_inventory sim ON UPPER(im.\"Product Code\") = UPPER(sim.sku) LEFT JOIN shopify_data sd ON UPPER (im.\"Product Code\") = UPPER(sd.sku) LEFT JOIN am_mrp_data az ON UPPER (im.\"Product Code\") = UPPER(az.sku) LEFT JOIN aj_mrp_data aj ON UPPER (im.\"Product Code\") = UPPER(aj.sku) LEFT JOIN my_mrp_data my ON UPPER (sku_group) = UPPER(my.sku_g) LEFT JOIN fk_mrp_data fk ON UPPER (im.\"Product Code\") = UPPER(fk.sku) LEFT JOIN nykaa_mrp_data ny ON UPPER (im.\"Product Code\") = UPPER(ny.sku) LEFT JOIN am ON sku_group = am.sku_group1 ) SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY sku ORDER BY sku) AS rn FROM final ) t QUALIFY rn = 1 ORDER BY sku; create or replace table snitch_db.maplemonk.omni_inventory_check as with store_inv as ( select logicusercode as sku, branch_name, sum(stock_qty) as total from snitch_db.maplemonk.LOgicerp23_24_get_stock_in_hand where date = current_date group by 1,2), wh_inv as ( SELECT \"Item SkuCode\" AS sku, sum(COALESCE(NULLIF(TRIM(inventory), \'\')::INTEGER, 0)) as sellable_uc, sum(COALESCE(NULLIF(TRIM(\"Bad Inventory\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(inventory), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Inventory Blocked\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Inventory Not Synced\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Not Found\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Putaway Pending\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Putback Pending\"), \'\')::INTEGER, 0) + COALESCE(NULLIF(TRIM(\"Stock In Transfer\"), \'\')::INTEGER, 0)) as total_uc FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND facility IN (\'SAPL_EMIZA\', \'SAPL-WH2\', \'SAPL-WH1\') group by 1 ), final as ( select si.*,wi.sellable_uc, wi.total_uc from store_inv si left join wh_inv wi on si.sku = wi.sku ) select * from final where total_uc < 2;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

